//! The suites, and which of them can run on the machine in front of you.
//!
//! Section 15.2 names seven of them and every one needs data that is either large, licensed, or
//! generated by a tool nobody has installed. That is normal for a benchmark harness and it is also
//! how a benchmark harness ends up never being run: the first suite anybody tries needs a 70 GB
//! download, so nobody tries a second time, so the apparatus rots until the week it is needed.
//!
//! So there is an eighth one that is not in the specification. `smoke` generates its own data in a
//! second, runs in a few more, and exercises the whole path: load, on-disk size, a cold run, five
//! hot runs, a distribution, a peak resident set and a per-query table. It measures nothing anybody
//! should quote and it proves the harness works, which is what M0 asks of it.

/// A benchmark suite, and what it needs before it can run.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Suite {
    /// The name the command line takes.
    pub name: &'static str,
    /// How many queries it has.
    pub queries: usize,
    /// What has to be true before it runs.
    pub needs: &'static str,
    /// Whether a number out of it is comparable to a public board.
    pub comparable: bool,
    /// What it is for, and what it is not for.
    pub note: &'static str,
}

/// Every suite this harness knows about, in the order section 15.2 lists them, with `smoke` first
/// because it is the only one that runs today.
pub const SUITES: &[Suite] = &[
    Suite {
        name: "smoke",
        queries: SMOKE.len(),
        needs: "nothing, it generates its own data",
        comparable: false,
        note: "Not a benchmark. Ten million rows of generated integers and strings, and six \
               queries over them that between them touch a scan, a filter, a sum, a group by, a \
               top k and a count distinct. It exists so the measurement path is exercised on every \
               commit rather than on the day somebody needs a real number and finds out the \
               harness rotted. Any figure from it is labelled smoke and goes nowhere near a README.",
    },
    Suite {
        name: "clickbench",
        queries: 43,
        needs: "hits at 99,997,497 rows, about 70 GB as TSV",
        comparable: true,
        note: "The board this project's headline claim is stated against. Run to the official \
               rules with the official script so the number is comparable, which means best of \
               three and the first run cold, and every number out of it is labelled \
               ClickBench-convention. Reported as the official Combined metric and as the raw sum, \
               because the sum is the diagnostic one and the Combined is the comparable one.",
    },
    Suite {
        name: "tpch",
        queries: 22,
        needs: "dbgen at SF10, SF100 and SF1000",
        comparable: true,
        note: "The three scales are three different measurements. SF10 fits in cache on a large \
               machine and measures the engine. SF100 is the standard comparison point. SF1000 \
               exceeds memory on most machines and measures spilling, which is where a lot of \
               engines quietly fall over and where a harness that only ran SF100 would have said \
               everything was fine.",
    },
    Suite {
        name: "tpcds",
        queries: 99,
        needs: "dsdgen at SF100",
        comparable: true,
        note: "All 99, including the ones that are unpleasant. The suite that punishes a narrow \
               optimizer, which makes it the one to watch while the optimizer is being written \
               rather than after.",
    },
    Suite {
        name: "job",
        queries: 113,
        needs: "the IMDb dataset",
        comparable: true,
        note: "Where Robust Predicate Transfer either works or does not. Reported with the \
               maximum per query ratio prominently and not only the mean, because the failure mode \
               being measured is one catastrophic plan and a mean is exactly the statistic that \
               hides one.",
    },
    Suite {
        name: "h2o",
        queries: 15,
        needs: "the h2o.ai generator",
        comparable: true,
        note: "Group by and join, fast to run and widely quoted, which makes it the best \
               regression canary in the list. Cheap enough to run on every nightly rather than \
               weekly.",
    },
    Suite {
        name: "micro",
        queries: 0,
        needs: "an engine to look inside",
        comparable: false,
        note: "Per encoding decode throughput, per kernel throughput, hash table insert and probe \
               rates, scan throughput at a range of selectivities, I/O throughput at a range of \
               queue depths. Subject to rule ten: a micro number never appears without the end to \
               end number it is supposed to explain, because a 20x kernel that moves the query by \
               three percent is an engineering note.",
    },
];

/// One query in a suite.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Query {
    /// What the table calls it.
    pub name: &'static str,
    /// The SQL, which has to be accepted by every engine in the comparison unmodified.
    pub sql: &'static str,
    /// What shape of work it is, so a table row can be read without reading the SQL.
    pub shape: &'static str,
}

/// The statements that build the smoke dataset.
///
/// Ten million rows is chosen so that the load is a second or two and a scan is tens of
/// milliseconds, which is far enough above a process spawn to be measuring the engine and far
/// enough below a coffee break to run on every commit. The string column is deliberately
/// low cardinality, because a dictionary is the first thing any of these engines does with one and
/// a smoke test that never exercises a dictionary is not exercising much.
pub const SMOKE_LOAD: &[&str] = &["CREATE TABLE smoke AS
       SELECT i AS id,
              (i * 2654435761) % 1000 AS k,
              (i % 97) / 7.0 AS v,
              'tag-' || ((i * 48271) % 64)::VARCHAR AS tag
       FROM range(10000000) t(i)"];

/// The smoke queries.
pub const SMOKE: &[Query] = &[
    Query { name: "q1", sql: "SELECT count(*) FROM smoke", shape: "count" },
    Query { name: "q2", sql: "SELECT sum(v) FROM smoke WHERE k < 100", shape: "filter and sum" },
    Query {
        name: "q3",
        sql: "SELECT tag, count(*) FROM smoke GROUP BY tag",
        shape: "group by, low card",
    },
    Query {
        name: "q4",
        sql: "SELECT k, sum(v) FROM smoke GROUP BY k ORDER BY 2 DESC LIMIT 10",
        shape: "group by and top k",
    },
    Query {
        name: "q5",
        sql: "SELECT count(DISTINCT tag) FROM smoke WHERE v > 5.0",
        shape: "count distinct",
    },
    Query {
        name: "q6",
        sql: "SELECT a.tag, count(*) FROM smoke a JOIN smoke b ON a.k = b.k \
              WHERE a.id < 100000 AND b.id < 100000 GROUP BY a.tag",
        shape: "join and group by",
    },
];

/// Find a suite by the name the command line was given.
#[must_use]
pub fn find(name: &str) -> Option<&'static Suite> {
    SUITES.iter().find(|s| s.name == name)
}

/// The queries of a suite, where this harness has them.
#[must_use]
pub fn queries(name: &str) -> Option<&'static [Query]> {
    match name {
        "smoke" => Some(SMOKE),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{SMOKE, SUITES, find, queries};

    #[test]
    fn the_only_suite_with_queries_in_it_is_the_one_that_runs() {
        for suite in SUITES {
            let has = queries(suite.name).is_some();
            assert_eq!(has, suite.name == "smoke", "{} disagrees with itself", suite.name);
        }
    }

    #[test]
    fn the_smoke_suite_counts_its_own_queries() {
        assert_eq!(find("smoke").unwrap().queries, SMOKE.len());
    }

    #[test]
    fn the_smoke_suite_is_not_comparable_to_anything() {
        // The flag is what a report reads to decide whether it may name a board. A smoke number
        // that claimed comparability would be the exact failure section 15.1 is written to prevent.
        assert!(!find("smoke").unwrap().comparable);
    }

    #[test]
    fn every_suite_says_what_it_needs_and_what_it_is_not_for() {
        for suite in SUITES {
            assert!(!suite.needs.is_empty(), "{} does not say what it needs", suite.name);
            assert!(suite.note.len() > 120, "{} needs a real note", suite.name);
        }
    }

    #[test]
    fn a_name_nobody_defined_is_none_rather_than_a_default() {
        assert!(find("clickbench-but-only-the-fast-ones").is_none());
    }

    #[test]
    fn the_smoke_queries_between_them_touch_the_shapes_that_matter() {
        let shapes: Vec<&str> = SMOKE.iter().map(|q| q.shape).collect();
        assert!(shapes.iter().any(|s| s.contains("group by")));
        assert!(shapes.iter().any(|s| s.contains("join")));
        assert!(shapes.iter().any(|s| s.contains("top k")));
    }
}
